INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5275', '2007-07-13', 'J', 'PLEISTOCENE STEALER', '''The last major one of these "glacial" time periods came during the Pleistocene Epoch''', 'an ice age', 1);
