INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5275', '2007-07-13', 'J', 'PLEISTOCENE STEALER', '''Utah''s Great Salt Lake is a remnant of this much larger Pleistocene lake that lent its name to some salt flats''', 'Bonneville', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5275', '2007-07-13', 'J', 'PLEISTOCENE STEALER', '''If you had a Smilodon smiling down on you, you were in trouble with one of these Pleistocene cats''', 'a saber-tooth tiger (or a lion)', 5);
