INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5802', '2009-12-01', 'DJ', 'POLAR OBSESSION', '''(<a href="http://www.j-archive.com/media/2009-12-01_DJ_14.jpg" target="_blank">Paul Nicklen presents the clue.</a>)  Walruses use ice as a safe place to rest & save energy; mom puts her pup on her <a href="http://www.j-archive.com/media/2009-12-01_DJ_14a.jpg" target="_blank">back</a> to protect against this species, Ursus maritimus, a major predator''', 'a polar bear', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5802', '2009-12-01', 'DJ', 'POLAR OBSESSION', '''(<a href="http://www.j-archive.com/media/2009-12-01_DJ_15.jpg" target="_blank">Paul Nicklen presents the clue.</a>)  Called oakum boys because their <a href="http://www.j-archive.com/media/2009-12-01_DJ_15a.jpg" target="_blank">brown down</a> looks like the frayed rope fiber used to caulk ships, <a href="http://www.j-archive.com/media/2009-12-01_DJ_15b.jpg" target="_blank">king penguin chicks</a> undergo this shedding process that gives them their waterproof feathers''', 'molting', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5802', '2009-12-01', 'DJ', 'POLAR OBSESSION', '''(<a href="http://www.j-archive.com/media/2009-12-01_DJ_16a.jpg" target="_blank">Paul Nicklen presents the clue.</a>)  Known for its <a href="http://www.j-archive.com/media/2009-12-01_DJ_16.jpg" target="_blank">ferocity,</a> the <a href="http://www.j-archive.com/media/2009-12-01_DJ_16b.jpg" target="_blank">seal</a> named for this big cat shows vast intelligence & is the only seal known to eat other species of seals''', 'a leopard', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5802', '2009-12-01', 'DJ', 'POLAR OBSESSION', '''(<a href="http://www.j-archive.com/media/2009-12-01_DJ_17a.jpg" target="_blank">Paul Nicklen presents the clue.</a>)  It''s easy to see why <a href="http://www.j-archive.com/media/2009-12-01_DJ_17.jpg" target="_blank">these</a> mammals are called unicorns of the sea; <a href="http://www.j-archive.com/media/2009-12-01_DJ_17b.jpg" target="_blank">that</a>''s not a horn, though--it''s actually a grooved tooth''', 'a narwhal', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5802', '2009-12-01', 'DJ', 'POLAR OBSESSION', '''(<a href="http://www.j-archive.com/media/2009-12-01_DJ_13.jpg" target="_blank">Paul Nicklen presents the clue.</a>)  Cliff-nesting birds, like the thousands seen <a href="http://www.j-archive.com/media/2009-12-01_DJ_13a.jpg" target="_blank">here</a>, play an important part in Arctic ecology; their guano falls before the icy water''s surface to provide nutrients to <a href="http://www.j-archive.com/media/2009-12-01_DJ_13b.jpg" target="_blank">these</a> flowery invertebrates''', 'sea anemones', 5);
