INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6292', '2012-01-17', 'DJ', 'NORWAY''S CULTURE & HISTORY', '''(<a href="http://www.j-archive.com/media/2012-01-17_DJ_22.jpg" target="_blank">Sarah of the Clue Crew sits at a kitchen table in Oslo, Norway.</a>)  A trip to Norway wouldn''t be complete without sampling lefse, the potato staple that folk legends say was given to slain warriors of this hall, to fortify them for battle''', 'Valhalla', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6292', '2012-01-17', 'DJ', 'NORWAY''S CULTURE & HISTORY', '''(<a href="http://www.j-archive.com/media/2012-01-17_DJ_23.jpg" target="_blank">Sarah of the Clue Crew stands in front of a large house at the Norsk Folkemuseum in Oslo, Norway.</a>) About 30 stave churches from the 12th and 13th century still stand here in Norway. The four corner posts, or staves, may represent these first four books of the New Testament''', 'Matthew, Mark, Luke, and John', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6292', '2012-01-17', 'DJ', 'NORWAY''S CULTURE & HISTORY', '''(<a href="http://www.j-archive.com/media/2012-01-17_DJ_24.jpg" target="_blank">Sarah of the Clue Crew stands before a tall sculpture in the Vigelund Sculpture Garden in Oslo, Norway.</a>) The centerpiece of Oslo''s Vigelund Sculpture Garden is a 57-foot <a href="http://www.j-archive.com/media/2012-01-17_DJ_24a.jpg" target="_blank">tower</a> depicting intertwined human figures reaching to the heavens; it''s known as this, from Latin for made from a single stone''', 'a monolith', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6292', '2012-01-17', 'DJ', 'NORWAY''S CULTURE & HISTORY', '''(<a href="http://www.j-archive.com/media/2012-01-17_DJ_25.jpg" target="_blank">Sarah of the Clue Crew stands in front of the Royal Palace in Oslo, Norway.</a>) King Harald V lives here, in Norway''s Royal Palace. He and his second cousin, England''s Queen Elizabeth, are both great-grandchildren of this British king, who ruled from 1901 to 1910.''', 'Edward VII', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6292', '2012-01-17', 'DJ', 'NORWAY''S CULTURE & HISTORY', '''(<a href="http://www.j-archive.com/media/2012-01-17_DJ_26.jpg" target="_blank">Sarah of the Clue Crew shows us a sod home at the Norsk Folkemuseum in Oslo, Norway.</a>) These people, also called Lapps, built turf or sod homes, called gammer that lasted thirty years or more in harsh conditions''', 'Sami', 5);
