INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('4982', '2006-04-18', 'DJ', 'SHRIMPING', '''(<a href="http://www.j-archive.com/media/2006-04-18_DJ_26.jpg" target="_blank">Sarah of the Clue Crew reports from a shrimp boat in Savannah, GA.</a>)  The bigger species of shrimp with the larger <a href="http://www.j-archive.com/media/2006-04-18_DJ_26a.jpg" target="_blank">nippers</a> on the second pair of thoracic legs are called these''', 'prawns', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('4982', '2006-04-18', 'DJ', 'SHRIMPING', '''(<a href="http://www.j-archive.com/media/2006-04-18_DJ_27.jpg" target="_blank">Sarah of the Clue Crew handles a net on a shrimp boat in Savannah, GA.</a>)  An excluder device called a <a href="http://www.j-archive.com/media/2006-04-18_DJ_27a.jpg" target="_blank">T.E.D.</a> helps this animal, such as the loggerhead, from getting caught in the net''', 'a turtle', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('4982', '2006-04-18', 'DJ', 'SHRIMPING', '''Shrimp can be a problem in Asia, as when they burrow they create muddy water that blocks photosynthesis for this crop''', 'rice', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('4982', '2006-04-18', 'DJ', 'SHRIMPING', '''(<a href="http://www.j-archive.com/media/2006-04-18_DJ_29.jpg" target="_blank">Sarah of the Clue Crew lets a deck hand do the dirty work on a shrimp boat in Savannah, GA.</a>)  A <a href="http://www.j-archive.com/media/2006-04-18_DJ_29a.jpg" target="_blank">technique</a> to cut open shrimp to take out the intestine shares its name with this diurnal insect''', 'butterfly', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('4982', '2006-04-18', 'DJ', 'SHRIMPING', '''(<a href="http://www.j-archive.com/media/2006-04-18_DJ_30.jpg" target="_blank">Kelly of the Clue Crew plays with her food on a shrimp boat in Savannah, GA.</a>)  Shrimp typically swim backwards by flexing the tail & <a href="http://www.j-archive.com/media/2006-04-18_DJ_30a.jpg" target="_blank">these</a> aptly-named appendages on the abdomen''', 'swimmerets', 5);
