INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5915', '2010-05-07', 'DJ', 'HOW LOW CAN YOU GO?', '''In a standard type of draw poker, you need a pair of these face cards also called knaves to open the betting''', 'jacks', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5915', '2010-05-07', 'DJ', 'HOW LOW CAN YOU GO?', '''"I went fishing just for the halibut" is one of these, which have been termed "the lowest form of wit"''', 'a pun', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5915', '2010-05-07', 'DJ', 'HOW LOW CAN YOU GO?', '''This chemical element has the lowest melting point of any metal & that''s why it''s liquid at room temperature''', 'mercury', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5915', '2010-05-07', 'DJ', 'HOW LOW CAN YOU GO?', '''An 1895 textbook calls this one-celled creature the lowest form of animal life''', 'an amoeba', 4);
