INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5915', '2010-05-07', 'DJ', 'SCIENCE', '''The word rubber comes from the discovery that the stuff could be used to rub out marks made with this''', 'pencil', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5915', '2010-05-07', 'DJ', 'SCIENCE', '''As it''s caused by a lack of niacin, pellagra is termed this type of deficiency disease''', 'vitamin deficiency', 2);
