INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5961', '2010-07-12', 'J', 'THE OLYMPIC GAMES', '''This is first lit by the sun''s rays at Olympia & then carried to the site of the games by runners''', 'the Olympic torch', 1);
