INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5961', '2010-07-12', 'J', 'I PITY DA FOOD!', '''Maine & spiny are types of this; its shell turns vivid red only affer it''s been cooked''', 'lobster', 1);
