INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5090', '2006-10-27', 'DJ', 'ROCK OF AGES', '''Here''s a changeup; the 3 classes of rock are igneous, sedimentary & this''', 'metamorphic', 1);
