INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5801', '2009-11-30', 'DJ', 'ARCHITECTURE', '''(<a href="http://www.j-archive.com/media/2009-11-30_DJ_01.jpg" target="_blank">Kelly of the Clue Crew shows some column styles on the monitor.</a>)  Of the three Greek orders, <a href="http://www.j-archive.com/media/2009-11-30_DJ_01.jpg" target="_blank">Doric</a> is the simplest, <a href="http://www.j-archive.com/media/2009-11-30_DJ_01a.jpg" target="_blank">Ionic</a> has spiral volutes, & <a href="http://www.j-archive.com/media/2009-11-30_DJ_01c.jpg" target="_blank">this</a> order decorated with <a href="http://www.j-archive.com/media/2009-11-30_DJ_01b.jpg" target="_blank">Acanthus leaves</a> is the most elaborate''', 'Corinthian', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5801', '2009-11-30', 'DJ', 'ARCHITECTURE', '''Egypt''s Old Cataract Hotel is an example of this architectural style named for a North African people''', 'the Moorish style', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5801', '2009-11-30', 'DJ', 'ARCHITECTURE', '''(<a href="http://www.j-archive.com/media/2009-11-30_DJ_04.jpg" target="_blank">Jimmy of the Clue Crew shows a floor plan on the monitor.</a>)  In a cruciform church, the central part is called the nave; it ends in a <a href="http://www.j-archive.com/media/2009-11-30_DJ_04a.jpg" target="_blank">recessed area</a> that is usually vaulted called this''', 'the apse', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5801', '2009-11-30', 'DJ', 'ARCHITECTURE', '''This word for a domed roof, often covering a rotunda, is from the Latin for "little cask"''', 'cupola', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5801', '2009-11-30', 'DJ', 'ARCHITECTURE', '''(<a href="http://www.j-archive.com/media/2009-11-30_DJ_06.jpg" target="_blank">Jimmy of the Clue Crew shows a castle wall on the monitor.</a>)  The name of <a href="http://www.j-archive.com/media/2009-11-30_DJ_06a.jpg" target="_blank">this</a> defensive wall comes from words meaning "protect" & "chest"; it''s still used as a protective barrier on bridges & balconies''', 'a parapet', 5);
