INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5490', '2008-06-20', 'DJ', 'SUMO', '''(<a href="http://www.j-archive.com/media/2008-06-20_DJ_26.jpg" target="_blank">Jimmy of the Clue Crew stands between two large men holding diapers.</a>) Quite a lot of this rich fabric goes into a "mawashi", which wraps several times around the sumo wrestler''', 'silk', 1);
