INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5490', '2008-06-20', 'DJ', 'SUMO', '''(<a href="http://www.j-archive.com/media/2008-06-20_DJ_29.jpg" target="_blank">Jimmy reports again from the match.</a>) Sumo wretlers take new names, sometimes ending with "kawa", meaning "river", or "yama", which is this appropriate geographical feature''', 'mountain', 4);
