INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6160', '2011-05-27', 'DJ', 'PINEAPPLES', '''(<a href="http://www.j-archive.com/media/2011-05-27_DJ_21.jpg" target="_blank">Sarah of the Clue Crew reports from a pineapple plantation.</a>)<br />Pineapples are the only widely eaten of the bromeliads--a family of 3,000 species; like others, they aren''t grown from seed, but by planting the top leafy structure, called this''', 'a crown', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6160', '2011-05-27', 'DJ', 'PINEAPPLES', '''(<a href="http://www.j-archive.com/media/2011-05-27_DJ_22.jpg" target="_blank">Sarah of the Clue Crew reports from a pineapple plantation.</a>)<br />Pineapple cultivation needs relatively little irrigation; with its reservoir formed in the leaves, the plant is a natural xerophyte--from the Greek "xeros", meaning this''', 'dry', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6160', '2011-05-27', 'DJ', 'PINEAPPLES', '''(<a href="http://www.j-archive.com/media/2011-05-27_DJ_23.jpg" target="_blank">Sarah of the Clue Crew reports from a pineapple plantation.</a>)<br />The pineapple shoots that grow from the mother plants after the main harvest are called the ratoon crop--also the Hawaiian term for a baby born to late-in-life parents, the word is thought to be from the Latin for this season''', 'autumn', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6160', '2011-05-27', 'DJ', 'PINEAPPLES', '''(<a href="http://www.j-archive.com/media/2011-05-27_DJ_29.jpg" target="_blank">Sarah of the Clue Crew reports from a pineapple plantation.</a>)<br />The material that''s laid down where pineapples are planted keeps weeds off, retains warmth, & keeps moisture in; though it''s a strip of plastic rather than organic material, it''s called this''', 'mulch', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6160', '2011-05-27', 'DJ', 'PINEAPPLES', '''(<a href="http://www.j-archive.com/media/2011-05-27_DJ_30.jpg" target="_blank">Sarah of the Clue Crew reports from a pineapple plantation.</a>)<br />Whether grown in Africa or here in Hawaii, pineapples have eight spirals in one direction and 13 in the other--one example where nature shows the number sequence named for this Italian mathematician''', 'Fibonacci', 5);
