INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5683', '2009-04-29', 'DJ', 'AROUND A GREEK TEMPLE', '''(<a href="http://www.j-archive.com/media/2009-04-29_DJ_21.jpg" target="_blank">Kelly of the Clue Crew shows an architectural graphic on the monitor.</a>)  The colonnaded entranceway is called the porch or this related longer word''', 'a portico', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5683', '2009-04-29', 'DJ', 'AROUND A GREEK TEMPLE', '''(<a href="http://www.j-archive.com/media/2009-04-29_DJ_23.wmv">Kelly of the Clue Crew shows an architectural graphic on the monitor.</a>)  The ring at the bottom of a column is called a torus; in math, a torus now refers to any donut-shaped figure for which the formula 4&#960;<sup>2</sup>Rr determines this''', 'area', 2);
