INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5683', '2009-04-29', 'DJ', 'AROUND A GREEK TEMPLE', '''(<a href="http://www.j-archive.com/media/2009-04-29_DJ_22.jpg" target="_blank">Jimmy of the Clue Crew shows an architectural graphic on the monitor.</a>)  At the top of the column, you''ll find <a href="http://www.j-archive.com/media/2009-04-29_DJ_22a.jpg" target="_blank">this</a> from the Latin for head; it''s the most important element in distinguishing the orders of Greek architecture''', 'a capital', 4);
