INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6122', '2011-04-05', 'J', 'OPRAH''S SURPRISES', '''(<a href="http://www.j-archive.com/media/2011-04-05_J_13.jpg" target="_blank">Oprah Winfrey gives the clue.</a>)  One of my favorite moments on the show is when a "Star Search" winner came on to sing "Isn''t She Lovely" & part way through found this man backing him up on a harmonica''', 'Stevie Wonder', 1);
