INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6195', '2011-07-15', 'J', 'LIFESAVING AT BONDI BEACH', '''(<a href="http://www.j-archive.com/media/2011-07-15_J_26.jpg" target="_blank">Sarah gives the clue from Bondi Beach.</a>) The familiar red-&-yellow flags & uniforms of Australia''s lifesavers originated with the maritime code  signals, in which a red-and-yellow flag stood for the letter "O", which was used to signal man in this predicament''', 'overboard', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6195', '2011-07-15', 'J', 'LIFESAVING AT BONDI BEACH', '''(<a href="http://www.j-archive.com/media/2011-07-15_J_27.jpg" target="_blank">Kelly gives the clue from Bondi Beach.</a>) In cold weather, hypothermia causes the body to lose heat faster than it can be produced; in hot weather, lifesavers often have to treat this opposite condition, from Greek for "overheating"''', 'hyperthermia', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6195', '2011-07-15', 'J', 'LIFESAVING AT BONDI BEACH', '''(<a href="http://www.j-archive.com/media/2011-07-15_J_28.jpg" target="_blank">Sarah gives the clue from Bondi Beach.</a>)  Emergency treatment for cardiac arrest often involves giving the victim''s chest an electrical shock, to jolt the heart out of the deadly state known as ventricular this, or v-fib''', 'fibrillation', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6195', '2011-07-15', 'J', 'LIFESAVING AT BONDI BEACH', '''(<a href="http://www.j-archive.com/media/2011-07-15_J_29.wmv">Sarah gives the clue from Bondi Beach.</a>) The evacuation siren & flag are used when one of these is approaching, as happened in February 2010, following an earthquake across the Pacific in Chile''', 'a tsunami', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6195', '2011-07-15', 'J', 'LIFESAVING AT BONDI BEACH', '''(<a href="http://www.j-archive.com/media/2011-07-15_J_30.wmv">Kelly of the Clue Crew gives the clue from a rescue boat off Bondi Beach.</a>)  Inflatable rescue boats are serious rescue tools, not bathtub toys, but here they''re affectionately called "rubber" these''', 'duckies', 5);
