INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5734', '2009-07-09', 'DJ', 'YOU: THE OWNER''S MANUAL', '''(<a href="http://www.j-archive.com/media/2009-07-09_DJ_07.jpg" target="_blank">Dr. Oz presents the clue.</a>)  Bones regenerate themselves every seven years, but after age 35, your <a href="http://www.j-archive.com/media/2009-07-09_DJ_07a.jpg" target="_blank">bones</a> grow slower & become less dense, which can lead to <a href="http://www.j-archive.com/media/2009-07-09_DJ_07b.jpg" target="_blank">this</a> condition, a thinning of bones''', 'osteoporosis', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5734', '2009-07-09', 'DJ', 'YOU: THE OWNER''S MANUAL', '''(<a href="http://www.j-archive.com/media/2009-07-09_DJ_08.wmv">Dr. Oz shows an animation of a throbbing artery in the brain on the monitor.</a>)  The brain is a beautiful place, but triggered by dilation of arteries in the brain, these extremely painful events are sometimes accompanied by nausea''', 'migraines', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5734', '2009-07-09', 'DJ', 'YOU: THE OWNER''S MANUAL', '''(<a href="http://www.j-archive.com/media/2009-07-09_DJ_09.wmv">Dr. Oz shows a cardiovascular animation on the monitor.</a>)  I try to be positive, but for just a little aversion therapy, here''s what it looks like when the arteries of the heart scar just before they cause a heart attack; this buildup here is called this''', 'plaque (atherosclerosis accepted)', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5734', '2009-07-09', 'DJ', 'YOU: THE OWNER''S MANUAL', '''(<a href="http://www.j-archive.com/media/2009-07-09_DJ_10.jpg" target="_blank">Dr. Oz puts a small pitcher to one nostril.</a>)  Just as you practice hygiene in your mouth, I advocate keeping your sinuses healthy with this device used in Asia for centuries''', 'a neti pot', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5734', '2009-07-09', 'DJ', 'YOU: THE OWNER''S MANUAL', '''(<a href="http://www.j-archive.com/media/2009-07-09_DJ_11.jpg" target="_blank">Dr. Oz holds a dissected human knee joint.</a>)  While pro athletes often tear the ACL shown <a href="http://www.j-archive.com/media/2009-07-09_DJ_11a.jpg" target="_blank">here</a>, regular folks often tear <a href="http://www.j-archive.com/media/2009-07-09_DJ_11b.jpg" target="_blank">this</a> cartilage in the middle of the knee that acts as a shock absorber''', 'the meniscus', 5);
