INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5533', '2008-10-01', 'J', 'NEWSEUM', '''(<a href="http://www.j-archive.com/media/2008-10-01_J_20.jpg" target="_blank">Sarah of the Clue Crew holds a flak jacket in the Newseum in Washington, D.C.</a>)  The Newseum has several exhibits on the dangers of journalism; this flak jacket was worn by this ABC anchor who was severely injured by a bomb in Iraq but, thankfully, returned to work''', 'Bob Woodruff', 5);
