INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5049', '2006-07-20', 'J', 'LET''S START A CLUB', '''(<a href="http://www.j-archive.com/media/2006-07-20_J_01.wmv">Sarah of the Clue Crew reports from the manufacturing facilities of Ping Hdqtrs in Phoenix, AZ.</a>)  At Ping, the first step of making golf irons is injecting hot wax into a mold of <a href="http://www.j-archive.com/media/2006-07-20_J_01a.jpg" target="_blank">this</a> malleable, silver-white metallic element''', 'aluminum', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5049', '2006-07-20', 'J', 'LET''S START A CLUB', '''(<a href="http://www.j-archive.com/media/2006-07-20_J_02.wmv">Sarah reads from the foundry of Ping Hdqtrs in Phoenix, AZ.</a>)  About 10% of clubs that are cast for Ping are for this type of golfer, like Phil Mickelson or Mike Weir''', 'a left-handed golfer', 2);
