INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5049', '2006-07-20', 'J', 'LET''S START A CLUB', '''(<a href="http://www.j-archive.com/media/2006-07-20_J_23.wmv">Jimmy of the Clue Crew lets off some steam in the foundry at Ping Hdqtrs in Phoenix, AZ.</a>)  One of the final steps is pouring this 2-word, rust-resistant alloy at about 2,975 degrees Fahrenheit to cast it as the club head''', 'stainless steel', 4);
