INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5355', '2007-12-14', 'DJ', 'LET''S LEARN HEBREW', '''(<a href="http://www.j-archive.com/media/2007-12-14_DJ_11.jpg" target="_blank">Jon of the Clue Crew shows a Hebrew word on a monitor.</a>) Hebrew is based on 3-letter roots.  The equivalent of "S", "D", "R" gives us "Sidrah", a Torah reading, "Siddur", a prayer book, and this word for a special meal''', 'seder', 1);
