INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5355', '2007-12-14', 'DJ', 'LET''S LEARN HEBREW', '''(<a href="http://www.j-archive.com/media/2007-12-14_DJ_13.jpg" target="_blank">Sarah of the Clue Crew gives us a Hebrew lesson.</a>) Hebrew letters can also indicate numbers; the word for 14 is yod-dalet, or 10 + 4; but 15 is <a href="http://www.j-archive.com/media/2007-12-14_DJ_13a.jpg" target="_blank">9 + 6</a> to avoid writing one of the many of these sacred names''', 'the names of God', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5355', '2007-12-14', 'DJ', 'LET''S LEARN HEBREW', '''Modern Hebrew uses Sephardic pronunciation, not that of these European Jews, so "Shabbat" not "Shabbes"''', 'Ashkenazi', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5355', '2007-12-14', 'DJ', 'LET''S LEARN HEBREW', '''(<a href="http://www.j-archive.com/media/2007-12-14_DJ_15.jpg" target="_blank">Kelly of the Clue Crew gives us a Hebrew lesson.</a>) In Hebrew, prefixes can be used as prepositions; "reshit" means "beginning", & <a href="http://www.j-archive.com/media/2007-12-14_DJ_15a.jpg" target="_blank">"b''reshit"</a> means this familliar phrase''', 'in the beginning', 5);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5355', '2007-12-14', 'FJ', 'ACADEMY AWARD FIRSTS', '''On March 5, 1936 screenwriter Dudley Nichols did this; it didn''t happen again until an actor did it April 15, 1971''', 'refused his Oscar', NULL);
