INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5370', '2008-01-04', 'J', 'KEN BURNS DOCUMENTARIES', '''(<a href="http://www.j-archive.com/media/2008-01-04_J_13.jpg" target="_blank">Ken delivers the clue once more.</a>) I made a film on this architect who claimed that his <a href="http://www.j-archive.com/media/2008-01-04_J_13a.jpg" target="_blank">Guggenheim</a> would make the nearby Metropolitan Museum look like a Protestant barn''', '(Frank Lloyd) Wright', 2);
