INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5526', '2008-09-22', 'DJ', 'RACING BIKES', '''(<a href="http://www.j-archive.com/media/2008-09-22_DJ_26.jpg" target="_blank">Jon of the Clue Crew presents from Trek Bicycle Corporation in Waterloo, WI.</a>)  In 1997, Trek Bikes signed <a href="http://www.j-archive.com/media/2008-09-22_DJ_26a.jpg" target="_blank">this</a> former world champion; he was an unknown quantity at the time due to his cancer diagnosis the year before''', 'Lance Armstrong', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5526', '2008-09-22', 'DJ', 'RACING BIKES', '''(<a href="http://www.j-archive.com/media/2008-09-22_DJ_27.jpg" target="_blank">Jon of the Clue Crew holds a bicycle frame at Trek Bicycle Corporation in Waterloo, WI.</a>)  Trek uses a proprietary method of optimum compaction & low void to maximize strength & minimize weight of <a href="http://www.j-archive.com/media/2008-09-22_DJ_27a.jpg" target="_blank">frames</a> & parts made of this element''', 'carbon', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5526', '2008-09-22', 'DJ', 'RACING BIKES', '''(<a href="http://www.j-archive.com/media/2008-09-22_DJ_28.wmv">Jon of the Clue Crew spins pedals and wheels at Trek Bicycle Corporation in Waterloo, WI.</a>)  Popular with bike messengers & recreational riders, track bikes are called "fixed" this, so the pedals turn with the wheels, like at the dawn of cycling''', 'fixed gear', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5526', '2008-09-22', 'DJ', 'RACING BIKES', '''(<a href="http://www.j-archive.com/media/2008-09-22_DJ_29.wmv">Sarah of the Clue Crew looks over a welder''s shoulder at Trek Bicycle Corporation in Waterloo, WI.</a>)  Hydroformed alloys of aluminum used in the <a href="http://www.j-archive.com/media/2008-09-22_DJ_29a.jpg" target="_blank">frame</a> keep the weight down while maintaining this, from the Latin for "stiffness"''', 'rigidity', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('5526', '2008-09-22', 'DJ', 'RACING BIKES', '''(<a href="http://www.j-archive.com/media/2008-09-22_DJ_30.jpg" target="_blank">Jon of the Clue Crew strolls through the factory of Trek Bicycle Corporation in Waterloo, WI.</a>)  Aeordynamics & lateral stiffness are key to bikes designed for <a href="http://www.j-archive.com/media/2008-09-22_DJ_30a.jpg" target="_blank">these</a> indoor tracks whose name comes from the French''', 'velodromes', 5);
