INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6207', '2011-09-20', 'J', 'EARLY MAN', '''(<a href="http://www.j-archive.com/media/2011-09-20_J_06.jpg" target="_blank">Sarah of the Clue Crew shows us a partial skull at the Smithsonian Hall of Human Origins.</a>)  Ouranopithecus macedoniensis, a 9-million-year-old ape from Greece, is a candidate as the long sought-for common ancestor of African apes & humans, popularly but inaccurately known by this two-word term''', 'the missing link', 1);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6207', '2011-09-20', 'J', 'EARLY MAN', '''790,000-year-old flints from a site in Israel provide the oldest known evidence of early man''s control of this''', 'fire', 2);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6207', '2011-09-20', 'J', 'EARLY MAN', '''(<a href="http://www.j-archive.com/media/2011-09-20_J_08.jpg" target="_blank">Kelly of the Clue Crew holds a small statue at the Smithsonian Hall of Human Origins.</a>)  This 35-thousand-year-old <a href="http://www.j-archive.com/media/2011-09-20_J_08a.jpg" target="_blank">figurine</a> known as the Lion Man, the oldest known human statue, is made from the ivory of this animal that went from endangered to extinct thousands of years ago''', 'the Woolly Mammoth', 3);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6207', '2011-09-20', 'J', 'EARLY MAN', '''The evolution of a large flexor pollicis muscle in this digit was key to early man''s ability to use tools''', 'the thumb', 4);
INSERT INTO questions (show_number, air_date, round, category, question, answer, sort_order) VALUES ('6207', '2011-09-20', 'J', 'EARLY MAN', '''(<a href="http://www.j-archive.com/media/2011-09-20_J_10a.jpg" target="_blank">Kelly of the Clue Crew holds a partial skull at the Smithsonian Hall of Human Origins.</a>) The enlarged brain of <a href="http://www.j-archive.com/media/2011-09-20_J_10.jpg" target="_blank">this</a> early human species helped it become the longest-lived member of the human family tree; named for its upright posture, it survived nine times longer than our species has been around''', 'Homo erectus', 5);
